const $=id=>document.getElementById(id),engine=QueueEngine;
const models=[['MM1','M/M/1','Um servidor, capacidade e população ilimitadas.'],['MMs','M/M/s > 1','Vários servidores em paralelo, capacidade ilimitada.'],['MM1K','M/M/1/K','Um servidor e capacidade total K. Chegadas com sistema cheio são recusadas.'],['MMsK','M/M/s > 1/K','Vários servidores e capacidade total K, incluindo o atendimento.'],['MM1N','M/M/1/N','Um servidor e população finita N. λ é a taxa por cliente fora do sistema.'],['MMsN','M/M/s > 1/N','Vários servidores e população finita N. λ é a taxa por cliente fora do sistema.'],['MG1','M/G/1','Um servidor, atendimento geral e capacidade ilimitada.']];
let model='MM1',last;
const f=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:5}), pct=n=>(n*100).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%',time=n=>f(n)+' '+$('unit').value+(n===1?'':'s');
function value(id){let raw=$(id).value.trim().replace(',','.');if(!raw||!Number.isFinite(Number(raw)))throw Error('Preencha todos os campos necessários com números válidos. Use vírgula ou ponto decimal, sem separador de milhar.');return Number(raw)}
function setup(){
 $('models').innerHTML=models.map(([id,label])=>`<button type="button" data-model="${id}" aria-pressed="${id===model}">${label}</button>`).join('');
 $('description').textContent=models.find(x=>x[0]===model)[2];$('model-tag').textContent=model==='MG1'?'Distribuição geral':'Markoviano';
 $('s-wrap').hidden=!model.includes('s');$('cap-wrap').hidden=!/[KN]$/.test(model);$('cap-label').textContent=model.endsWith('N')?'População finita · N':'Capacidade total · K';$('known-wrap').hidden=model!=='MM1';if(model!=='MM1')$('known').value='rates';$('variability').hidden=model!=='MG1';update();stale();
}
function update(){let u=$('unit').value;
 for(const key of ['arrival','service']){const mode=$(key+'-mode').value,unit=$(key+'-base').selectedOptions[0].textContent.toLowerCase();$(key+'-unit').textContent=mode==='rate'?'clientes/'+unit:mode==='time'?unit+'s':'clientes';$(key+'-period-wrap').hidden=mode!=='count';}
 $('arrival-help').textContent=model.endsWith('N')?'Para população finita, informe por cliente fora do sistema.':'Use a média de chegadas ao sistema.';
 const mode=$('known').value, labels={lambdaRho:['Taxa de chegada λ · clientes/'+u,'Utilização ρ · entre 0 e 1'],LW:['Clientes no sistema L','Tempo no sistema W · '+u+'s'],LqWq:['Clientes na fila Lq','Espera na fila Wq · '+u+'s'],lambdaLq:['Taxa de chegada λ · clientes/'+u,'Clientes na fila Lq'],lambdaW:['Taxa de chegada λ · clientes/'+u,'Tempo no sistema W · '+u+'s'],muRho:['Taxa de atendimento μ · clientes/'+u,'Utilização ρ · entre 0 e 1'],lambdaL:['Taxa de chegada λ · clientes/'+u,'Clientes médios no sistema L'],lambdaWq:['Taxa de chegada λ · clientes/'+u,'Espera média na fila Wq · '+u+'s'],WWq:['Tempo no sistema W · '+u+'s','Espera na fila Wq · '+u+'s']};
 $('rate-inputs').hidden=mode!=='rates';$('inverse-inputs').hidden=mode==='rates';if(labels[mode]){[$('x-label').textContent,$('y-label').textContent]=labels[mode];}
 $('cv-help').textContent=({'cv':'CV = σ / E[S]. Use 0 para tempo constante ou 1 para o caso exponencial.','sd':'Desvio padrão na unidade de tempo escolhida.','variance':'Variância na unidade de tempo ao quadrado.','second':'E[S²] na unidade de tempo ao quadrado; deve ser ≥ E[S]².'})[$('cv-mode').value];
}
function stale(){if(last){$('status').textContent='Dados alterados · recalcule';$('output').hidden=true;$('empty').hidden=false;} }
function rate(key){const n=value(key);if(n<=0)throw Error('Taxas, tempos e contagens devem ser maiores que zero.');const mode=$(key+'-mode').value,factor=({hora:3600,minuto:60,segundo:1,dia:86400})[$('unit').value]/Number($(key+'-base').value);if(mode==='rate')return n*factor;if(mode==='time')return factor/n;const period=value(key+'-period');if(period<=0)throw Error('A duração do intervalo deve ser maior que zero.');return n/period*factor;}
function run(example=false){try{let params={model,s:model.includes('s')?value('s'):1};if(model.includes('s')&&params.s<2)throw Error('Para o modelo s > 1, informe pelo menos 2 servidores.');
 if($('known').value==='rates'){params.lambda=rate('arrival');params.mu=rate('service');}else Object.assign(params,engine.inverse($('known').value,value('x'),value('y')));
 if(model.endsWith('K'))params.K=value('cap');if(model.endsWith('N'))params.N=value('cap');
 if(model==='MG1'){const n=value('cv'),m=$('cv-mode').value;if(n<0)throw Error('A variabilidade não pode ser negativa.');params.cv=m==='cv'?n:m==='sd'?n*params.mu:m==='variance'?Math.sqrt(n)*params.mu:Math.sqrt(Math.max(0,n*params.mu**2-1));if(m==='second'&&n*params.mu**2<1-1e-10)throw Error('E[S²] deve ser maior ou igual ao quadrado do tempo médio de atendimento.');}
 const r=engine.calculate(params);last={params,result:r};$('error').hidden=true;$('empty').hidden=true;$('output').hidden=false;$('status').textContent=example?'Exemplo calculado':'Resultado atualizado';render(r);
 }catch(e){$('error').textContent=e.message;$('error').hidden=false;$('output').hidden=true;$('empty').hidden=false;$('status').textContent='Confira os dados';}}
function render(r){const rows=[['L','Clientes no sistema',f(r.L),'clientes'],['Lq','Clientes aguardando',f(r.Lq),'clientes'],['W','Tempo total no sistema',time(r.W),''],['Wq','Espera na fila',time(r.Wq),''],['ρ','Ocupação média por servidor',pct(r.rho),''],['P₀','Probabilidade de sistema vazio',pct(r.p0),''],['λef','Taxa efetiva de chegada',f(r.effective),'clientes/'+$('unit').value],['λ','Taxa de chegada informada',f(r.lambda),model.endsWith('N')?'por cliente/'+$('unit').value:'clientes/'+$('unit').value],['μ','Atendimento por servidor',f(r.mu),'clientes/'+$('unit').value]];
 if(r.block!==null)rows.push(['Pᴋ','Probabilidade de bloqueio',pct(r.block),'']);if(r.wait!==null)rows.push(['Pesp','Chance de esperar ao entrar',pct(r.wait),'']);
 $('output').innerHTML=`<div class="lead"><div><p>Espera média antes do atendimento</p><strong>${f(r.Wq)} <span style="font-size:19px">${$('unit').value}${r.Wq===1?'':'s'}</span></strong><p>${f(r.Lq)} clientes aguardando, em média.</p></div><div class="util"><b>${pct(r.rho)}</b><div class="meter"><span style="width:${r.rho*100}%"></span></div><p>ocupação</p></div></div><table><thead><tr><th scope="col">Medida</th><th scope="col">Descrição</th><th scope="col">Resultado</th></tr></thead><tbody>${rows.map(([s,d,v,u])=>`<tr><td class="symbol">${s}</td><td>${d}</td><td><b>${v}</b><small>${u}</small></td></tr>`).join('')}</tbody></table><details><summary>Como este resultado foi calculado</summary><p class="formula">${r.method}</p><p>Chegadas e atendimentos independentes, servidores idênticos e disciplina FCFS. Lei de Little: L = λef × W e Lq = λef × Wq. ${model.endsWith('N')?'População finita: a taxa total de chegada varia com o estado; N não é uma taxa nem uma capacidade de bloqueio.':''}</p></details>${r.probs?`<details><summary>Probabilidades por número de clientes</summary><div class="chart" role="img" aria-label="Probabilidades de zero a ${Math.min(r.probs.length,30)-1} clientes no sistema">${r.probs.slice(0,30).map((p,n)=>`<div class="bar" style="height:${Math.max(.4,p/Math.max(...r.probs)*100)}%" title="P(${n}) = ${pct(p)}"></div>`).join('')}</div><p class="chart-note">Barras: n = 0 a ${Math.min(r.probs.length,30)-1}. Valores completos abaixo${!/[KN]$/.test(model)?'; a lista mostra um trecho da distribuição infinita':''}.</p><label for="n">Consultar P(n) · número de clientes no sistema</label><input id="n" inputmode="numeric" value="0"><p id="pn"></p><div style="max-height:220px;overflow:auto"><table><thead><tr><th>n</th><th>P(n)</th></tr></thead><tbody>${r.probs.map((p,n)=>`<tr><td>${n}</td><td>${pct(p)}</td></tr>`).join('')}</tbody></table></div></details>`:'<p class="hint">Em M/G/1, média e variância não bastam para calcular a distribuição completa P(n). A chance de esperar é ρ, pois uma chegada de Poisson encontra o servidor ocupado com essa probabilidade.</p>'}<details><summary>Referências e convenções</summary><p><a href="https://web.stanford.edu/class/ee384x/EE384X/handouts/H10.pdf" target="_blank" rel="noopener">Stanford · Fórmula de Pollaczek–Khinchine</a></p><p>Material da disciplina: Teoria das filas Modelo MMs.pdf, Prof. Dr. Paulo Roberto Maia, páginas 27–50.</p><p>Nos modelos exponenciais, resolvemos as equações de equilíbrio de nascimento e morte; nos ilimitados, usamos Erlang C. K inclui os clientes em atendimento. N é a população finita.</p></details>`;
 if(model==='MM1'||model==='MMs'){const box=document.createElement('details');box.innerHTML='<summary>Probabilidades de exceder um limite</summary><label for=threshold>Limite de clientes r · P(n > r)</label><input id=threshold value=5 inputmode=numeric><label for=limit>Tempo t · '+$('unit').value+'s</label><input id=limit value=1 inputmode=decimal><p id=tails></p>';$('output').append(box);const showTails=()=>{try{const v=engine.tails(r,value('limit'),value('threshold'));$('tails').textContent='P(n > r) = '+pct(v.count)+' · P(W > t) = '+pct(v.system)+' · P(Wq > t) = '+pct(v.queue);}catch(e){$('tails').textContent=e.message;}};$('limit').oninput=showTails;$('threshold').oninput=showTails;showTails();}
 if($('n')){const show=()=>{try{const n=value('n');if(!Number.isInteger(n)||n<0||n>100000)throw Error('Use um inteiro de 0 a 100.000.');let p;if(/[KN]$/.test(model))p=r.probs[n]||0;else{let log=Math.log(r.p0);for(let i=1;i<=n;i++)log+=Math.log(r.lambda/(Math.min(i,r.s)*r.mu));p=Math.exp(log);}$('pn').textContent=`P(${n}) = ${pct(p)}`;}catch(e){$('pn').textContent=e.message;}};$('n').addEventListener('input',show);show();}}
 $('models').addEventListener('click',e=>{if(e.target.dataset.model){model=e.target.dataset.model;setup();}});$('form').addEventListener('submit',e=>{e.preventDefault();run();});$('form').addEventListener('input',()=>{update();stale();});$('form').addEventListener('change',()=>{update();stale();});$('example').onclick=()=>{ $('known').value='rates';$('arrival-mode').value='rate';$('service-mode').value='rate';$('arrival').value=model.endsWith('N')?'0,2':'8';$('service').value='12';$('s').value='2';$('cap').value='10';$('cv-mode').value='cv';$('cv').value='1';$('arrival-base').value='3600';$('service-base').value='3600';$('unit').value='hora';update();run(true);};$('print').onclick=()=>window.print();setup();run(true);
